      +'<div class="bs-actions"><a class="bs-btn" href="#bs-catalog" data-catalog>Find your book '+icon('arrow')+'</a>'+link('book',feature.id,'Read about the featured book','bs-text-link')+'</div></div>'
      +'<div class="bs-hero-media">'+link('book',feature.id,image(feature,true),'bs-feature-image')+'<div class="bs-feature-label"><div><strong>'+e(feature.title)+'</strong><span>'+e(feature.summary||feature.subtitle)+'</span></div>'+link('book',feature.id,icon('arrow'),'bs-text-link')+'</div></div></div></section>'
      +'<div class="bs-proof"><div>'+icon('book')+'Digital books</div><div>'+icon('phone')+'Read on your phone</div><div>'+icon('mail')+'Download + email link</div></div>'
      +'<section class="bs-section" id="bs-catalog" aria-labelledby="bs-catalog-title"><div class="bs-section-title"><div><span class="bs-kicker">The collection</span><h2 id="bs-catalog-title">What would you like to work on?</h2><p>'+e(cfg.catalog_intro||'Explore books by title or topic.')+'</p></div><label class="bs-search">'+icon('search')+'<input type="search" id="bs-search" placeholder="Search by title or topic" aria-label="Search books" value="'+e(state.search)+'"></label></div>'
      +'<div class="bs-filters" aria-label="Book categories">'+cats.map(c=>'<button type="button" class="bs-chip" data-filter="'+e(c)+'" aria-pressed="'+(c===state.filter)+'">'+e(c)+'</button>').join('')+'</div><div class="bs-books" id="bs-book-grid">'+grid()+'</div><p class="bs-form-help" id="bs-results" aria-live="polite">'+resultsLabel()+'</p><div id="bs-pagination">'+pagination()+'</div></section>'
      +'<section class="bs-section" aria-labelledby="bs-how-title"><span class="bs-kicker">From choosing to reading</span><h2 id="bs-how-title">Getting your book is simple.</h2><div class="bs-steps"><div><span class="bs-step-number">01</span><h3>Find books that fit</h3><p>See what each book covers and add the ones you want to your cart.</p></div><div><span class="bs-step-number">02</span><h3>Check your total and pay</h3><p>We show the price in your currency. Check your total, enter your details and complete payment.</p></div><div><span class="bs-step-number">03</span><h3>Download and start reading</h3><p>After we confirm payment, download your books. We also send their download links to your email.</p></div></div></section>'
      +'<section class="bs-help-band"><div><h2>Not sure where to start?</h2><p>Tell us what you want help with. We will help you choose a suitable book.</p></div>'+link('contact',null,'Send us a message '+icon('arrow'),'bs-btn bs-outline')+'</section>'
      +'<section class="bs-faq"><div><span class="bs-kicker">Before you buy</span><h2>A few useful answers.</h2><p>Have another question? '+link('contact',null,'Ask us here.','bs-text-link')+'</p></div><div>'
      +'<details><summary>Can I buy more than one book?</summary><p>Yes. Add the titles you want to your cart and pay once. After payment, download them separately or together in one ZIP file. We also email all your download links.</p></details>'
      +'<details><summary>Will I receive a printed book?</summary><p>You are buying a digital book. Download the file and read it on a phone, tablet or computer. The pictures show the book cover designs.</p></details>'
