  applyTheme();window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(state.theme==='system')applyTheme();});
  render();
  if(!cfg.preview){countTimer=setTimeout(refreshCounts,15000);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refreshCounts();});}
  locateCountry();
  root.addEventListener('click',ev=>{const pick=ev.target.closest('[data-consent-choice]');if(pick){const yes=pick.dataset.consentChoice==='yes';if(window.BSTracking?.setConsent?.(yes)){if(yes&&state.page==='book'){const book=chosen();if(book)window.BSTracking.track('ViewContent',{content_ids:[book.id],content_type:'product',content_name:book.title,value:amountFor(book)||undefined,currency:countryInfo[state.country].currency});}render();}return;}if(ev.target.closest('[data-consent-reset]')){window.BSTracking?.resetChoice?.();render();}});
